/// The `CompletionPort` implementation this platform actually uses.
///
/// Every desktop/mobile target this workspace builds for has exactly one
/// sensible backend, so callers that just want "the port for this machine"
/// -- a camera capture loop, a host's I/O thread -- should name this instead
/// of repeating the `cfg` ladder and silently getting it wrong on one
/// platform. Code that deliberately targets a specific backend (benchmarks
/// comparing two of them, backend-specific tests) should keep naming that
/// backend directly.
///
/// Note that `PlatformPort` does not imply [`ReadinessPort`]: `IocpPort`
/// deliberately does not implement it, because IOCP has no readiness model
/// for an anonymous pipe. Code that needs readiness must bound on
/// [`ReadinessPort`] and provide a Windows path of its own.
#[cfg(target_os = "linux")]
pub type PlatformPort = IoUringPort;
#[cfg(any(
    target_os = "macos",
    target_os = "ios",
    target_os = "freebsd",
    target_os = "openbsd",
    target_os = "netbsd",
    target_os = "dragonfly"
))]
pub type PlatformPort = KqueuePort;
#[cfg(target_os = "android")]
pub type PlatformPort = EpollPort;
#[cfg(windows)]
pub type PlatformPort = IocpPort;

/// Builds a [`Proactor`] on this platform's [`PlatformPort`].
#[cfg(any(
    target_os = "linux",
    target_os = "macos",
    target_os = "ios",
    target_os = "freebsd",
    target_os = "openbsd",
    target_os = "netbsd",
    target_os = "dragonfly",
    target_os = "android",
    windows
))]
pub fn new_platform_proactor() -> io::Result<Proactor<PlatformPort>> {
    Ok(Proactor::new(PlatformPort::new()?))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompletionKind {
    Exit,
    Job,
    Net,
    Io,
    Timer,
    User(u64),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Completion {
    pub kind: CompletionKind,
    pub bytes_transferred: u32,
}

pub trait CompletionHandler: Send + 'static {
    fn run(self: Box<Self>, completion: Completion);
}

impl<F> CompletionHandler for F
where
    F: FnOnce(Completion) + Send + 'static,
{
    fn run(self: Box<Self>, completion: Completion) {
        (self)(completion);
    }
}

pub struct CompletionEnvelope {
    completion: Completion,
    handler: Box<dyn CompletionHandler>,
}

impl CompletionEnvelope {
    pub fn new(
        kind: CompletionKind,
        bytes_transferred: u32,
        handler: impl CompletionHandler,
    ) -> Self {
        Self {
            completion: Completion {
                kind,
                bytes_transferred,
            },
            handler: Box::new(handler),
        }
    }

    pub fn completion(&self) -> Completion {
        self.completion
    }

    fn dispatch(self) {
        self.handler.run(self.completion);
    }
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ReadinessEvent {
    pub token: u64,
}

/// Token values [`ProactorHandle::register_readable`] refuses.
///
/// `IoUringPort` uses `user_data` 1 and 2 for its own completion-queue
/// and wake markers, and dispatches readiness out of that same space, so
/// a registration on either value is silently swallowed there. The values
/// are rejected on every backend rather than only on io_uring so that a
/// token which works on one platform cannot quietly do nothing on
/// another.
#[cfg(unix)]
pub const RESERVED_READINESS_TOKENS: [u64; 2] = [1, 2];

#[cfg(unix)]
pub trait ReadinessHandler: Send + 'static {
    fn on_ready(&mut self, readiness: ReadinessEvent);
}

#[cfg(unix)]
impl<F> ReadinessHandler for F
where
    F: FnMut(ReadinessEvent) + Send + 'static,
{
    fn on_ready(&mut self, readiness: ReadinessEvent) {
        (self)(readiness);
    }
}

pub enum PollEvent {
    Completion(CompletionEnvelope),
    /// A completed `IoPort` operation, already fully resolved by the
    /// backend into a ready-to-run thunk (it already looked up the
    /// buffer/handler for whatever `IoOpId` the kernel's completion named
    /// and built the real `IoResult`/`AcceptResult`/etc.) -- `Proactor`
    /// just runs it, the same way it runs a `CompletionEnvelope`.
    IoCompletion(Box<dyn FnOnce() + Send>),
    #[cfg(unix)]
    Readiness(ReadinessEvent),
    Wake,
    Timeout,
}

pub trait CompletionPort: Send + Sync + 'static {
    fn post(&self, envelope: CompletionEnvelope) -> io::Result<()>;
    fn poll(&self, timeout: Option<Duration>) -> io::Result<PollEvent>;
